+            assertThat(claimed).hasSize(1);
+            assertThat(claimed.get(0).id()).isEqualTo(id);
+            assertThat(claimed.get(0).attempts()).isEqualTo(1);
+            assertThat(claimed.get(0).availableAt()).isAfter(now.plusMillis(4000));
